/* scanf(3) demonstration: Reading formatted input with error checking */
#include <stdio.h>
#include <stdlib.h>

int main() {
    int num_items = 2;
    char name[50];
    int age;
    int count;

    printf("Enter your name (max 49 chars) and your age: ");

    // Attempt to read a string (%49s) and an integer (%d)
    // The number 49 prevents buffer overflow in 'name'.
    count = scanf("%49s %d", name, &age);

    if (count == EOF) {
        // Handle EOF (End-Of-File) or read error
        if (feof(stdin)) {
            fprintf(stderr, "\nInput stream ended before data was read.\n");
        } else {
            perror("Read Error");
        }
        return 1;
    }

    if (count != num_items) {
        // Handle conversion/matching failure (e.g., user entered 'twenty' for age)
        fprintf(stderr, "Error: Expected %d matches, only successful with %d.\n", num_items, count);

        // Clear the remaining bad input from the buffer
        while (getchar() != '\n' && !feof(stdin) && !ferror(stdin));
        return 1;
    }

    printf("\nData successfully parsed:\n");
    printf("Name: %s\n", name);
    printf("Age: %d\n", age);

    return 0;
}
